// Package regexp implements the gomplate `regexp` template-function
// namespace. All functions coerce their arguments with the same lenient
// semantics as the reference tool: any value is stringified (nil becomes
// the string "nil"), and numeric arguments are parsed leniently.
package regexp

import (
	"fmt"
	stdregexp "regexp"
	"strconv"
)

// ns is the namespace value whose methods are the template functions.
type ns struct{}

// NS returns the regexp namespace: a pointer to a struct whose methods
// implement the documented `regexp.*` template functions.
func NS() any { return &ns{} }

// toString mirrors the reference tool's string coercion: nil becomes
// "nil", everything else uses fmt's %v formatting (strings pass through
// unchanged, float64 2.0 prints as "2", maps as "map[k:v]", ...).
func toString(v any) string {
	if v == nil {
		return "nil"
	}
	return fmt.Sprintf("%v", v)
}

// toInt64 coerces v to an int64 with the reference tool's semantics and
// error texts. Strings are parsed base-prefix aware as integers first,
// then as floats (truncating toward zero); the reported error for strings
// is the strconv.ParseFloat failure. Non-string, non-numeric values
// produce a bare "could not convert" error.
func toInt64(v any) (int64, error) {
	switch n := v.(type) {
	case int:
		return int64(n), nil
	case int8:
		return int64(n), nil
	case int16:
		return int64(n), nil
	case int32:
		return int64(n), nil
	case int64:
		return n, nil
	case uint:
		return int64(n), nil
	case uint8:
		return int64(n), nil
	case uint16:
		return int64(n), nil
	case uint32:
		return int64(n), nil
	case uint64:
		return int64(n), nil
	case float32:
		return int64(n), nil
	case float64:
		return int64(n), nil
	case bool:
		if n {
			return 1, nil
		}
		return 0, nil
	case string:
		if i, err := strconv.ParseInt(n, 0, 64); err == nil {
			return i, nil
		}
		if f, err := strconv.ParseFloat(n, 64); err == nil {
			return int64(f), nil
		} else {
			return 0, fmt.Errorf("could not convert %q to int64: %w", n, err)
		}
	}
	return 0, fmt.Errorf("could not convert %v to int64", v)
}

// Find implements `regexp.Find`: the leftmost match of expression in
// input. A compile failure is returned bare (no prefix).
func (n *ns) Find(expression, input any) (string, error) {
	re, err := stdregexp.Compile(toString(expression))
	if err != nil {
		return "", err
	}
	return re.FindString(toString(input)), nil
}

// FindAll implements `regexp.FindAll`: all successive matches. Called as
// FindAll expression input or FindAll expression n input; n defaults to
// -1 (all matches). A compile failure is returned bare (no prefix).
func (n *ns) FindAll(expression any, args ...any) ([]string, error) {
	num, input, err := nArgs(args)
	if err != nil {
		return nil, err
	}
	re, err := stdregexp.Compile(toString(expression))
	if err != nil {
		return nil, err
	}
	return re.FindAllString(toString(input), num), nil
}

// Match implements `regexp.Match`: true if expression matches input.
func (n *ns) Match(expression, input any) (bool, error) {
	re, err := stdregexp.Compile(toString(expression))
	if err != nil {
		return false, fmt.Errorf("error compiling expression: %w", err)
	}
	return re.MatchString(toString(input)), nil
}

// QuoteMeta implements `regexp.QuoteMeta`: escape all regexp
// metacharacters in input.
func (n *ns) QuoteMeta(input any) string {
	return stdregexp.QuoteMeta(toString(input))
}

// Replace implements `regexp.Replace`: ReplaceAllString semantics ($
// variables in the replacement are expanded).
func (n *ns) Replace(expression, replacement, input any) (string, error) {
	re, err := stdregexp.Compile(toString(expression))
	if err != nil {
		return "", fmt.Errorf("error compiling expression: %w", err)
	}
	return re.ReplaceAllString(toString(input), toString(replacement)), nil
}

// ReplaceLiteral implements `regexp.ReplaceLiteral`:
// ReplaceAllLiteralString semantics (the replacement is used verbatim).
func (n *ns) ReplaceLiteral(expression, replacement, input any) (string, error) {
	re, err := stdregexp.Compile(toString(expression))
	if err != nil {
		return "", fmt.Errorf("error compiling expression: %w", err)
	}
	return re.ReplaceAllLiteralString(toString(input), toString(replacement)), nil
}

// Split implements `regexp.Split`: split input around matches of the
// expression. Called as Split expression input or Split expression n
// input; n defaults to -1 (all substrings).
func (n *ns) Split(expression any, args ...any) ([]string, error) {
	num, input, err := nArgs(args)
	if err != nil {
		return nil, err
	}
	re, err := stdregexp.Compile(toString(expression))
	if err != nil {
		return nil, fmt.Errorf("error compiling expression: %w", err)
	}
	return re.Split(toString(input), num), nil
}

// nArgs parses the trailing arguments of FindAll/Split: either (input) or
// (n, input). The n conversion is validated before the expression is
// compiled, matching the reference tool's error precedence.
func nArgs(args []any) (num int, input any, err error) {
	if len(args) != 1 && len(args) != 2 {
		return 0, nil, fmt.Errorf("wrong number of args: want 2 or 3, got %d", len(args)+1)
	}
	num = -1
	input = args[len(args)-1]
	if len(args) == 2 {
		i64, err := toInt64(args[0])
		if err != nil {
			return 0, nil, fmt.Errorf("n must be an integer: %w", err)
		}
		num = int(i64)
	}
	return num, input, nil
}

package regexp

import (
	"bytes"
	"strings"
	"testing"
	"text/template"
)

func render(t *testing.T, tmpl string) (string, error) {
	t.Helper()
	fmap := template.FuncMap{"regexp": func() any { return NS() }}
	tt, err := template.New("<arg>").Option("missingkey=error").Funcs(fmap).Parse(tmpl)
	if err != nil {
		return "", err
	}
	var buf bytes.Buffer
	err = tt.Execute(&buf, map[string]any{"Env": map[string]string{}})
	return buf.String(), err
}

func TestRender(t *testing.T) {
	tests := []struct {
		name    string
		tmpl    string
		want    string
		wantErr string // substring of the rendered template error
	}{
		// regexp.Find
		{"find basic", `{{ regexp.Find "[a-z]{3}" "foobar"}}`, "foo", ""},
		{"find no match", `no {{ "will not match" | regexp.Find "[0-9]" }}numbers`, "no numbers", ""},
		{"find coerces int input", `{{ regexp.Find "[0-9]" 123 }}`, "1", ""},
		{"find coerces int expression", `{{ regexp.Find 9 "foo9bar" }}`, "9", ""},
		{"find nil expression", `{{ regexp.Find (index . "nope") "nil" }}`, "nil", ""},
		{"find empty pattern", `{{ regexp.Find "" "abc" }}`, "", ""},
		{"find empty match on empty input", `{{ regexp.Find "z*" "" }}`, "", ""},
		{"find pipeline", `{{ "foobar" | regexp.Find "[a-z]{3}" }}`, "foo", ""},
		{"find bad regex", `{{ regexp.Find "(" "foo" }}`, "",
			`error calling Find: error parsing regexp: missing closing ): ` + "`(`"},
		{"find wrong arg count", `{{ regexp.Find "[a]" "a" "extra" }}`, "",
			"wrong number of args for Find: want 2 got 3"},

		// regexp.FindAll
		{"findall 2 args", `{{ printf "%v" (regexp.FindAll "[a-z]{3}" "foobar") }}`, "[foo bar]", ""},
		{"findall 3 args", `{{ printf "%v" ("foo bar baz qux" | regexp.FindAll "[a-z]{3}" 3) }}`, "[foo bar baz]", ""},
		{"findall pipeline 2 args", `{{ printf "%v" ("abc" | regexp.FindAll "[a-z]") }}`, "[a b c]", ""},
		{"findall n=0", `{{ if regexp.FindAll "[0-9]" 0 "a1b2c3" }}non-empty{{ else }}empty{{ end }}`, "empty", ""},
		{"findall n=0 len", `{{ len (regexp.FindAll "[0-9]" 0 "a1b2c3") }}`, "0", ""},
		{"findall negative n", `{{ printf "%v" (regexp.FindAll "[0-9]" -2 "a1b2c3") }}`, "[1 2 3]", ""},
		{"findall float n truncates", `{{ printf "%v" (regexp.FindAll "[0-9]" 2.9 "a1b2c3") }}`, "[1 2]", ""},
		{"findall float string n", `{{ printf "%v" (regexp.FindAll "[0-9]" "2.5" "a1b2c3") }}`, "[1 2]", ""},
		{"findall bool n", `{{ printf "%v" (regexp.FindAll "[0-9]" true "a1b2c3") }}`, "[1]", ""},
		{"findall hex string n", `{{ printf "%v" (regexp.FindAll "a" "0x2" "aaxaa") }}`, "[a a]", ""},
		{"findall empty pattern", `{{ printf "%v" (regexp.FindAll "" "abc") }}`, "[   ]", ""},
		{"findall zero-width matches", `{{ printf "%v" (regexp.FindAll "a*" "baa") }}`, "[ aa]", ""},
		{"findall bad regex", `{{ regexp.FindAll "[" 2 "foo" }}`, "",
			"error calling FindAll: error parsing regexp: missing closing ]: `[`"},
		{"findall bad n string", `{{ regexp.FindAll "[a]" "x" "foo" }}`, "",
			`error calling FindAll: n must be an integer: could not convert "x" to int64: strconv.ParseFloat: parsing "x": invalid syntax`},
		{"findall n with spaces", `{{ regexp.FindAll "a" " 2 " "aaxaa" }}`, "",
			`error calling FindAll: n must be an integer: could not convert " 2 " to int64: strconv.ParseFloat: parsing " 2 ": invalid syntax`},
		{"findall nil n", `{{ regexp.FindAll "a" (index . "nope") "aaa" }}`, "",
			"error calling FindAll: n must be an integer: could not convert <nil> to int64"},
		{"findall n error precedes regex error", `{{ regexp.FindAll "(" "x" "foo" }}`, "",
			`error calling FindAll: n must be an integer: could not convert "x" to int64`},
		{"findall no args", `{{ regexp.FindAll }}`, "",
			"error calling FindAll: wrong number of args: want 2 or 3, got 0"},
		{"findall one arg", `{{ regexp.FindAll "a" }}`, "",
			"error calling FindAll: wrong number of args: want 2 or 3, got 1"},
		{"findall four args", `{{ regexp.FindAll "[a]" "foo" "bar" "baz" }}`, "",
			"error calling FindAll: wrong number of args: want 2 or 3, got 4"},
		{"findall five args", `{{ regexp.FindAll "a" "b" "c" "d" "e" }}`, "",
			"error calling FindAll: wrong number of args: want 2 or 3, got 5"},

		// regexp.Match
		{"match true", `{{ regexp.Match "^h" "hello" }}`, "true", ""},
		{"match false", `{{ regexp.Match "^h" "bye" }}`, "false", ""},
		{"match pipeline", `{{ "foo" | regexp.Match "^f" }}`, "true", ""},
		{"match bool expression", `{{ regexp.Match true "true" }}`, "true", ""},
		{"match case sensitive", `{{ regexp.Match "^TRUE$" true }}`, "false", ""},
		{"match float input", `{{ regexp.Match "[a]" 3.14 }}`, "false", ""},
		{"match nil input", `{{ regexp.Match "a" (index . "nope") }}`, "false", ""},
		{"match empty both", `{{ regexp.Match "" "" }}`, "true", ""},
		{"match bad regex", `{{ regexp.Match "(" "foo" }}`, "",
			"error calling Match: error compiling expression: error parsing regexp: missing closing ): `(`"},

		// regexp.QuoteMeta
		{"quotemeta braces", `{{ ` + "`{hello}`" + ` | regexp.QuoteMeta }}`, `\{hello\}`, ""},
		{"quotemeta plus", `{{ regexp.QuoteMeta "a+b" }}`, `a\+b`, ""},
		{"quotemeta int", `{{ regexp.QuoteMeta 123 }}`, "123", ""},
		{"quotemeta float", `{{ regexp.QuoteMeta 2.5 }}`, `2\.5`, ""},
		{"quotemeta nil", `{{ regexp.QuoteMeta (index . "nope") }}`, "nil", ""},
		{"quotemeta wrong arg count", `{{ regexp.QuoteMeta "a" "b" }}`, "",
			"wrong number of args for QuoteMeta: want 1 got 2"},

		// regexp.Replace
		{"replace group", `{{ regexp.Replace "(foo)bar" "$1" "foobar"}}`, "foo", ""},
		{"replace named groups", `{{ regexp.Replace "(?P<first>[a-zA-Z]+) (?P<last>[a-zA-Z]+)" "${last}, ${first}" "Alan Turing"}}`, "Turing, Alan", ""},
		{"replace int replacement", `{{ regexp.Replace "o" 0 "foo" }}`, "f00", ""},
		{"replace int input", `{{ regexp.Replace "o" "x" 100 }}`, "100", ""},
		{"replace dollar-dollar", `{{ regexp.Replace "x" "$$" "x" }}`, "$", ""},
		{"replace unmatched group", `{{ regexp.Replace "x" "${1}" "x" }}`, "", ""},
		{"replace $0", `{{ regexp.Replace "o" "$0" "foo" }}`, "foo", ""},
		{"replace empty replacement", `{{ regexp.Replace "a" "" "aaa" }}`, "", ""},
		{"replace bad regex", `{{ regexp.Replace "[" "x" "foo" }}`, "",
			"error calling Replace: error compiling expression: error parsing regexp: missing closing ]: `[`"},

		// regexp.ReplaceLiteral
		{"replaceliteral dollar", `{{ regexp.ReplaceLiteral "(foo)bar" "$1" "foobar"}}`, "$1", ""},
		{"replaceliteral pipeline", `{{ ` + "`foo.bar,baz`" + ` | regexp.ReplaceLiteral ` + "`\\W` `$`" + ` }}`, "foo$bar$baz", ""},
